ROOT = Path(__file__).resolve().parents[1]


def load_json(rel, default):
    p = ROOT / rel
    if not p.exists():
        return default
    return json.loads(p.read_text(encoding="utf-8"))


def save_json(rel, value):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(value, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")


def upsert(items, obj, key="id"):
    for i, item in enumerate(items):
        if isinstance(item, dict) and item.get(key) == obj.get(key):
            items[i] = obj
            return
    items.append(obj)


def append_once(items, obj, match_key="date"):
    marker = obj.get(match_key)
    text = obj.get("summary") or obj.get("note") or obj.get("url")
    for existing in items:
        if isinstance(existing, dict) and existing.get(match_key) == marker and (existing.get("summary") or existing.get("note") or existing.get("url")) == text:
            return
    items.append(obj)


